mapper.select:
select /* SYS10000MMapper.selectMenuList */ cm.menu_id ,cm.parent_menu_cd ,cm.child_menu_cd ,cm.child_menu_nm ,cm.child_page_ulr ,cm.child_menu_level ,cm.child_menu_seq ,cm.user_yn ,cm.btn_search_yn ,cm.btn_search_init_yn ,cm.btn_save_yn ,cm.btn_add_row_yn ,cm.btn_del_row_yn ,cm.btn_excel_down_yn ,cm.btn_excel_up_yn ,cm.btn_print_yn ,cm.btn_batch_yn ,cm.remark from com_menu cm where 1=1
and cm.user_yn = #{USER_YN}
order by cm.child_menu_seq ,cm.menu_id
